package app.noir.mobile;
import android.app.job.*;
public final class SyncJobService extends JobService {
 final java.util.Map<Integer,DataStore.WorkCancel> cancellations=new java.util.HashMap<>();final java.util.Map<Integer,java.util.concurrent.Future<?>> tasks=new java.util.HashMap<>();
 @Override public boolean onStartJob(JobParameters p){String profile=p.getExtras().getString("profile","");final DataStore captured;try{captured=profile.isEmpty()?NoirApp.data:NoirApp.dataFor(this,profile);}catch(RuntimeException e){return false;}if(captured==null)return false;final DataStore.WorkCancel work=new DataStore.WorkCancel();cancellations.put(p.getJobId(),work);tasks.put(p.getJobId(),captured.network.submit(()->{DataStore.workCancel.set(work);boolean retry=false;try{if(work.stopped)return;if(captured.paired()){try{if(TvUi.isTv(this))captured.sync();else BackgroundSync.run(captured,p.getJobId()==701);if(!work.stopped&&NoirApp.data==captured)PhonePickupJob.kick(this);}catch(Exception ignored){retry=true;}}if(!work.stopped&&NoirApp.data==captured&&captured.prefs().optBoolean("alerts",true)){EpisodeAlerts.refreshPhoneSchedules(this);if(!work.stopped)EpisodeAlerts.check(this);}if(!work.stopped&&NoirApp.data==captured)PhoneReadyJob.refill(this);}finally{DataStore.workCancel.remove();Thread.interrupted();work.connections.clear();boolean reschedule=retry||captured.hasOutbox();new android.os.Handler(getMainLooper()).post(()->{if(cancellations.get(p.getJobId())==work){cancellations.remove(p.getJobId());tasks.remove(p.getJobId());if(!work.stopped)jobFinished(p,reschedule);}});}}));return true;}
 @Override public boolean onStopJob(JobParameters p){DataStore.WorkCancel work=cancellations.remove(p.getJobId());if(work!=null)work.cancel();java.util.concurrent.Future<?> task=tasks.remove(p.getJobId());if(task!=null)task.cancel(true);return true;}
}
